// v3nc03_cluster_scaling / ex1 - reference solution (author only, used by `dojo verify`).

export interface Balancer {
  next(): string | undefined;
  setHealth(id: string, healthy: boolean): void;
  healthy(): string[];
}

export function createRoundRobin(ids: readonly string[]): Balancer {
  const ring = [...ids];
  const up = new Set(ring);
  let cursor = 0;

  return {
    next(): string | undefined {
      // Walk the full ring, not a filtered copy: filtering would renumber
      // every worker whenever health changed, producing repeats and skips.
      for (let tried = 0; tried < ring.length; tried++) {
        const candidate = ring[cursor];
        cursor = (cursor + 1) % ring.length;
        if (up.has(candidate)) return candidate;
      }
      // Bounded loop, so an all-unhealthy set returns instead of spinning.
      return undefined;
    },

    setHealth(id: string, healthy: boolean): void {
      // A message from a worker that no longer exists must not add a phantom.
      if (!ring.includes(id)) return;
      if (healthy) up.add(id);
      else up.delete(id);
    },

    // Original order, not rotation order: this is a report, not a schedule.
    healthy(): string[] {
      return ring.filter((id) => up.has(id));
    },
  };
}

// v3nc03_cluster_scaling / ex2 - reference solution (author only, used by `dojo verify`).

export interface LeastConnections {
  acquire(): string | undefined;
  release(id: string): void;
  load(): Record<string, number>;
}

export function createLeastConnections(ids: readonly string[]): LeastConnections {
  const counts = new Map<string, number>(ids.map((id) => [id, 0]));
  let cursor = 0;

  return {
    acquire(): string | undefined {
      const all = [...counts.keys()];
      if (all.length === 0) return undefined;

      const min = Math.min(...all.map((id) => counts.get(id) ?? 0));
      const tied = all.filter((id) => (counts.get(id) ?? 0) === min);

      // Rotating among the tied workers only: without this, an idle cluster
      // sends every request to whichever id happens to be first.
      const chosen = tied[cursor % tied.length];
      cursor = (cursor + 1) % Math.max(1, tied.length);

      counts.set(chosen, min + 1);
      return chosen;
    },

    release(id: string): void {
      const current = counts.get(id);
      if (current === undefined) return;
      // Clamp rather than throw: a double release should not create a worker
      // with a negative count, which would be a permanent traffic magnet.
      counts.set(id, Math.max(0, current - 1));
    },

    load(): Record<string, number> {
      return Object.fromEntries(counts);
    },
  };
}

