// v3nc03_cluster_scaling / ex7 - reference solution (author only, used by `dojo verify`).

export interface CounterPrimary {
  handle(childId: number, message: unknown): { to: number; reply: unknown } | undefined;
  value(key: string): number;
}

interface Request {
  id: number;
  op: string;
  key: string;
  by?: number;
  limit?: number;
}

export function createCounterPrimary(): CounterPrimary {
  const counts = new Map<string, number>();

  return {
    handle(childId: number, message: unknown): { to: number; reply: unknown } | undefined {
      const request = message as Request | null;
      if (!request || typeof request.id !== "number" || typeof request.key !== "string") {
        return undefined;
      }

      switch (request.op) {
        case "incr": {
          const value = (counts.get(request.key) ?? 0) + (request.by ?? 1);
          counts.set(request.key, value);
          return { to: childId, reply: { id: request.id, value } };
        }

        case "get":
          return { to: childId, reply: { id: request.id, value: counts.get(request.key) ?? 0 } };

        case "reserve": {
          // Check and increment in one handler. Split across two messages this
          // is a race: two workers both read 99 and both decide they may pass.
          const next = (counts.get(request.key) ?? 0) + 1;
          if (next > (request.limit ?? 0)) {
            // Do not count rejected attempts: doing so locks a client out for
            // the rest of the window after their first burst.
            return { to: childId, reply: { id: request.id, allowed: false } };
          }
          counts.set(request.key, next);
          return { to: childId, reply: { id: request.id, allowed: true } };
        }

        default:
          return undefined;
      }
    },

    value(key: string): number {
      return counts.get(key) ?? 0;
    },
  };
}

// A child spawned with stdio slot 3 set to "ipc" gets process.send and
// process.on("message") without fork() being involved at all.
export const CHILD_SOURCE = `
process.on("message", (m) => {
  if (m.type !== "work") return;
  process.send({ id: m.id, op: "reserve", key: m.key, limit: m.limit });
});
process.send({ type: "ready" });
`;

