// v3nc03_cluster_scaling / ex8 - reference solution (author only, used by `dojo verify`).
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import type { Socket } from "node:net";

export interface Drainable {
  url(): string;
  connections(): number;
  drain(options?: { deadlineMs?: number }): Promise<"clean" | "forced">;
}

export function createDrainableServer(
  handler: (req: IncomingMessage, res: ServerResponse) => void,
): Promise<Drainable> {
  return new Promise<Drainable>((resolve, reject) => {
    const sockets = new Set<Socket>();
    const server = createServer(handler);

    // server.close() waits for connections to end but cannot tell an idle
    // keep-alive socket from a busy one, so we keep the list ourselves.
    server.on("connection", (socket) => {
      sockets.add(socket);
      socket.once("close", () => sockets.delete(socket));
    });

    server.once("error", reject);
    // Port 0: the OS picks a free port, which is the only way two test files
    // can run at once without colliding.
    server.listen(0, "127.0.0.1", () => {
      const address = server.address();
      const port = typeof address === "object" && address ? address.port : 0;

      let draining: Promise<"clean" | "forced"> | undefined;

      resolve({
        url: () => `http://127.0.0.1:${port}`,
        connections: () => sockets.size,

        drain(options: { deadlineMs?: number } = {}): Promise<"clean" | "forced"> {
          // Idempotent: a second call joins the first rather than repeating it.
          if (draining) return draining;
          const deadlineMs = options.deadlineMs ?? 1000;

          draining = new Promise<"clean" | "forced">((done) => {
            let outcome: "clean" | "forced" = "clean";

            const timer = setTimeout(() => {
              outcome = "forced";
              // After the deadline, not instead of it: destroying a socket
              // mid-request gives the client a reset with no status at all.
              server.closeAllConnections();
            }, deadlineMs);
            timer.unref?.();

            server.close(() => {
              clearTimeout(timer);
              done(outcome);
            });
            // The line that turns a five-minute deploy into a fast one.
            server.closeIdleConnections();
          });

          return draining;
        },
      });
    });
  });
}

