export interface WorkerReport {
  workerId: string;
  counts: Record<string, number>;
}

export interface MergeResult {
  totals: Record<string, number>;
  overLimit: string[];
  falseAllows: Record<string, number>;
}

export function mergeWindows(reports: readonly WorkerReport[], limit: number): MergeResult {
  const totals: Record<string, number> = {};
  for (const report of reports) {
    for (const [key, count] of Object.entries(report.counts)) {
      totals[key] = (totals[key] ?? 0) + count;
    }
  }

  const overLimit: string[] = [];
  const falseAllows: Record<string, number> = {};
  for (const [key, total] of Object.entries(totals)) {
    if (total <= limit) continue;
    overLimit.push(key);
    // The size of the hole per-process state left in a limit we believed we
    // were enforcing: requests served that one shared counter would have
    // rejected.
    falseAllows[key] = total - limit;
  }

  // Sorted, because a report whose order changes when nothing changed is a
  // report nobody trusts.
  overLimit.sort();

  return { totals, overLimit, falseAllows };
}
